function createVoiceControlledRacingGame(canvasId) {
    const canvas = document.getElementById(canvasId);
    const ctx = canvas.getContext('2d');
    const width = 500;
    const height = 500;
    canvas.width = width;
    canvas.height = height;

    let carX = width / 2;
    let carY = height - 50;
    let carSpeed = 0;
    let lapTime = 0;
    let bestLapTime = Infinity;
    let raceStarted = false;
    let raceCompleted = false;
    let mute = false;

    const audioContext = new (window.AudioContext || window.webkitAudioContext)();
    let microphoneStream;
    let analyser = audioContext.createAnalyser();
    analyser.fftSize = 256;
    let bufferLength = analyser.frequencyBinCount;
    let dataArray = new Uint8Array(bufferLength);

    function startMicrophone() {
        navigator.mediaDevices.getUserMedia({ audio: true })
            .then(stream => {
                microphoneStream = stream;
                const source = audioContext.createMediaStreamSource(stream);
                source.connect(analyser);
            })
            .catch(err => {
                console.error('Error accessing microphone:', err);
                alert('Please allow microphone access to use the voice-controlled racing game.');
            });
    }

    function updateVolume() {
        analyser.getByteFrequencyData(dataArray);
        let sum = 0;
        for (let i = 0; i < bufferLength; i++) {
            sum += dataArray[i];
        }
        let average = sum / bufferLength;
        return average / 128;
    }

    function drawCar() {
        ctx.fillStyle = 'red';
        ctx.fillRect(carX, carY, 20, 30);
    }

    function drawTrack() {
        ctx.fillStyle = 'green';
        ctx.fillRect(0, 0, width, height);
    }

    function drawVolumeMeter(volume) {
        ctx.fillStyle = 'blue';
        ctx.fillRect(width - 50, 0, 50, volume * height);
    }

    function drawLapTime() {
        ctx.fillStyle = 'black';
        ctx.font = '16px Arial';
        ctx.fillText(`Lap Time: ${lapTime.toFixed(2)}s`, 10, 20);
        ctx.fillText(`Best Lap: ${bestLapTime === Infinity ? 'N/A' : bestLapTime.toFixed(2)}s`, 10, 40);
    }

    function checkCrash() {
        if (carX < 0 || carX > width - 20 || carY < 0 || carY > height - 30) {
            return true;
        }
        return false;
    }

    function handleCrash() {
        raceCompleted = true;
        carSpeed = 0;
        console.log('Crashed!');
    }

    function handleRaceCompletion() {
        if (raceCompleted && lapTime < bestLapTime) {
            bestLapTime = lapTime;
            console.log('New Best Lap!');
        }
        console.log('Race Completed!');
    }

    function handleStartRace() {
        raceStarted = true;
        lapTime = 0;
        carX = width / 2;
        carY = height - 50;
        carSpeed = 0;
    }

    function handleMuteToggle() {
        mute = !mute;
        if (microphoneStream) {
            microphoneStream.getTracks()[0].enabled = !mute;
        }
    }

    function drawUI() {
        ctx.fillStyle = 'white';
        ctx.font = '16px Arial';
        ctx.fillText('Start Race', width / 2 - 50, 20);
        ctx.fillText('Mute/Unmute', width / 2 - 50, 40);
    }

    function handleMouseClick(x, y) {
        if (x > width / 2 - 50 && x < width / 2 + 50 && y > 10 && y < 30) {
            handleStartRace();
        } else if (x > width / 2 - 50 && x < width / 2 + 50 && y > 30 && y < 50) {
            handleMuteToggle();
        }
    }

    function animate() {
        requestAnimationFrame(animate);
        ctx.clearRect(0, 0, width, height);
        drawTrack();
        drawCar();
        drawVolumeMeter(updateVolume());
        drawLapTime();

        if (raceStarted && !raceCompleted) {
            if (!mute) {
                carSpeed = updateVolume() * 5;
            }
            carX += carSpeed;
            lapTime += 1 / 60;
            if (checkCrash()) {
                handleCrash();
            }
        }

        if (raceCompleted) {
            handleRaceCompletion();
        }

        drawUI();
    }

    canvas.addEventListener('click', (event) => {
        const rect = canvas.getBoundingClientRect();
        const x = event.clientX - rect.left;
        const y = event.clientY - rect.top;
        handleMouseClick(x, y);
    });

    startMicrophone();
    animate();
}
